template <typename T> class ClassName { /* ... */ }; // Class template

// Specialization for specific type
template <> class ClassName<SpecificType> { /* specialized implementation */ };

// Function template with type deduction
template <typename T>
void functionName(T param) { /* ... */ }

// Using auto for type deduction
auto variableName = expression; // compiler deduces type based on expression
